def icon(name: str, cls: str = "") -> Markup:
    """SVG decorativo: il significato è sempre anche nel testo accanto."""
    body = ICONS.get(name)
    if body is None:
        return Markup("")
    extra = f" {cls}" if cls else ""
    return Markup(
        f'<svg class="icon{extra}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" '
        'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" '
        f'stroke-linejoin="round" aria-hidden="true" focusable="false">{body}</svg>'
    )
